// WF-7 guard — validate state
const state = $input.first().json;
if (!state || state.schema_version !== 1) throw new Error(`WF-7: invalid schema_version`);
return [{ json: state }];

// WF-7 query Qdrant tool_store and problem_store
const state = $('Guard: validate state').first().json;
const embedResp = $input.first().json;
const vector = embedResp.embeddings ? embedResp.embeddings[0] : embedResp.embedding;
if (!vector) throw new Error('WF-7: no embedding returned');
// Store vector for next nodes
return [{ json: { state, vector } }];

// WF-7 assemble recall: reusable_tools (ranked by similarity × log(1+fitness)) + mutation_constraints
// E7-3: problem hits are rewritten by small fast model (qwen2.5:1.5b) into imperative constraints
const state = $('Extract vector').first().json.state;
const toolHits = $('Qdrant: search tool_store').first().json.result || [];
const problemHits = $('Qdrant: search problem_store').first().json.result || [];
const ranked = toolHits.map(h => {
  const fitness = h.payload?.fitness || 1;
  const rank = h.score * Math.log(1 + fitness);
  return { ...h, _rank: rank };
}).sort((a,b) => b._rank - a._rank);
const reusable_tools = ranked.slice(0,3).map(h => ({
  tool_name: h.payload.tool_name,
  code: h.payload.code,
  description: h.payload.description,
  input_schema: h.payload.input_schema,
  score: h.score,
  fitness: h.payload.fitness || 1,
  rank: h._rank
}));
// For E7-3, if problemHits exist, we will call the mutation-rewrite small model in the next node
// Here we prepare the raw failure texts for that node
const rawFailures = problemHits.map(h => `Goal: ${h.payload?.goal||''} Error: ${h.payload?.error||''} Summary: ${(h.payload?.code_summary||'').slice(0,200)}`);
return [{ json: { state, reusable_tools, rawFailures, problemHits } }];

// WF-7 final assemble — merge small-model constraints
const prev = $('Prep reuse + raw failures').first().json;
const llm = $input.first().json;
let constraints = [];
if (prev.rawFailures.length === 0) {
  constraints = [];
} else if (llm.response) {
  // LLM returns 1-3 lines, split
  constraints = llm.response.split('\n').filter(l => l.trim()).slice(0,3);
} else {
  // Fallback to simple transform if LLM failed
  constraints = prev.rawFailures.map(f => `A similar attempt failed: ${f.slice(0,120)}. Mutate by changing approach.`);
}
const next = JSON.parse(JSON.stringify(prev.state));
next.recall = next.recall || {};
next.recall.reusable_tools = prev.reusable_tools;
next.recall.mutation_constraints = (next.recall.mutation_constraints||[]).concat(constraints).slice(0,3);
return [{ json: next }];
